BEGIN IMMEDIATE;
CREATE TABLE accounts(id TEXT PRIMARY KEY,label TEXT NOT NULL,appearance TEXT NOT NULL,preferences TEXT,last_visit INTEGER);
CREATE TABLE credentials(id TEXT PRIMARY KEY,account TEXT NOT NULL REFERENCES accounts(id) ON DELETE CASCADE,data TEXT NOT NULL);
CREATE TABLE sessions(hash TEXT PRIMARY KEY,account TEXT NOT NULL REFERENCES accounts(id) ON DELETE CASCADE,csrf TEXT NOT NULL,verified INTEGER NOT NULL,expires INTEGER NOT NULL);
CREATE TABLE recovery(hash TEXT PRIMARY KEY,account TEXT NOT NULL REFERENCES accounts(id) ON DELETE CASCADE);
CREATE TABLE visits(account TEXT NOT NULL REFERENCES accounts(id) ON DELETE CASCADE,device TEXT NOT NULL,active INTEGER NOT NULL,cutoff INTEGER,PRIMARY KEY(account,device));
CREATE TABLE reading(account TEXT NOT NULL REFERENCES accounts(id) ON DELETE CASCADE,post TEXT NOT NULL,bookmarked INTEGER NOT NULL DEFAULT 0,read INTEGER NOT NULL DEFAULT 0,PRIMARY KEY(account,post));
CREATE TABLE releases(id TEXT PRIMARY KEY,data TEXT NOT NULL,created INTEGER NOT NULL);
CREATE TABLE published(singleton INTEGER PRIMARY KEY CHECK(singleton=1),release TEXT NOT NULL REFERENCES releases(id));
CREATE TABLE restrictions(post TEXT PRIMARY KEY,observed INTEGER NOT NULL);
CREATE TABLE current_posts(post TEXT PRIMARY KEY,hidden INTEGER NOT NULL,source TEXT NOT NULL,rendition TEXT);
CREATE TABLE renditions(id TEXT PRIMARY KEY,post TEXT NOT NULL,source TEXT NOT NULL,run TEXT NOT NULL,text TEXT NOT NULL);
CREATE TABLE source_revisions(id TEXT PRIMARY KEY,post TEXT NOT NULL,data TEXT NOT NULL);
CREATE TABLE feedback(account TEXT NOT NULL REFERENCES accounts(id) ON DELETE CASCADE,post TEXT NOT NULL,rendition TEXT NOT NULL REFERENCES renditions(id),dimension TEXT NOT NULL CHECK(dimension IN ('emotions','head')),score INTEGER NOT NULL CHECK(score BETWEEN -10 AND 10),seq INTEGER NOT NULL,PRIMARY KEY(account,rendition,dimension));
CREATE TABLE feedback_clears(account TEXT NOT NULL REFERENCES accounts(id) ON DELETE CASCADE,post TEXT NOT NULL,dimension TEXT NOT NULL,seq INTEGER NOT NULL,PRIMARY KEY(account,post,dimension));
CREATE TABLE sequence(value INTEGER NOT NULL);
INSERT INTO sequence VALUES(0);
CREATE TABLE ratings(account TEXT NOT NULL REFERENCES accounts(id) ON DELETE CASCADE,post TEXT NOT NULL,level TEXT NOT NULL CHECK(level IN ('dug-in','no-change','new-light','changed-mind')),PRIMARY KEY(account,post));
CREATE TABLE historical(name TEXT PRIMARY KEY,data TEXT NOT NULL);
PRAGMA user_version=1;
COMMIT;
